import { useEffect, useState } from "react";
import { Platform, type ImageSourcePropType } from "react-native";
import snapshotJson from "../../store/studio.json";
import { BUNDLED_ICONS } from "./icons.generated";

/**
 * The live studio apps — design/APP-ABOUT-STANDARD.md § 4. The bundled snapshot in store/studio.json (generated by
 * scripts/sync-studio-kit.py from projects/app-stores/apps.json — never hand-edited) is the source by DEFAULT, renewed
 * with every build or OTA update. The runtime read of jukkablomberg.com/data/apps.json is OPT-IN (`live`): a request
 * to a second domain must be named in the app's privacy page first — UsePhysics promises no network request at all,
 * the atlases and FatTonic name exactly one host (2026-10-07 port review). "Live" = a store page that answered 200; review and
 * internal tracks are not live. Generated copy: edit projects/app-stores/studio-kit/src/, then run the sync.
 */
export type StudioApp = {
  slug: string;
  venture: string;
  promo: string | null;
  cluster: string;
  tierRank: number;
  icon?: string;
  ios: { url: string } | null;
  android: { url: string; package: string } | null;
};
type Snapshot = {
  registryUrl: string;
  developer: { android: string | null; ios: string | null };
  apps: StudioApp[];
  /** this app's own cluster (bundled snapshot only) — affinity works before the app itself is live */
  self?: { slug: string; cluster: string };
};

const snapshot = snapshotJson as unknown as Snapshot;
let memo: Snapshot | null = null;

function valid(x: unknown): x is Snapshot {
  const s = x as Snapshot;
  return !!s && Array.isArray(s.apps) && s.apps.every((a) => typeof a.slug === "string" && typeof a.venture === "string");
}

export function iconFor(app: StudioApp): ImageSourcePropType | null {
  const bundled = (BUNDLED_ICONS as Record<string, ImageSourcePropType>)[app.slug];
  if (bundled) return bundled;
  return app.icon ? { uri: app.icon } : null;
}

/** Other live apps on THIS device's store, by affinity: same cluster, then charter tier, then name. */
export function useStudioApps(self: string, live = false): { apps: StudioApp[]; developerUrl: string | null } {
  const [data, setData] = useState<Snapshot>((live && memo) || snapshot);
  useEffect(() => {
    if (!live || memo) return;
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 4000);
    fetch(snapshot.registryUrl, { signal: ctl.signal })
      .then((r) => (r.ok ? r.json() : null))
      .then((j) => {
        if (valid(j)) {
          memo = j;
          setData(j);
        }
      })
      .catch(() => undefined)
      .finally(() => clearTimeout(timer));
    return () => {
      clearTimeout(timer);
      ctl.abort();
    };
  }, [live]);
  const platform = Platform.OS === "ios" ? "ios" : "android";
  const mine = snapshot.self?.cluster ?? data.apps.find((a) => a.slug === self)?.cluster;
  const apps = data.apps
    .filter((a) => a.slug !== self && a[platform])
    .sort((a, b) => {
      const ca = a.cluster === mine ? 0 : 1;
      const cb = b.cluster === mine ? 0 : 1;
      return ca - cb || a.tierRank - b.tierRank || a.venture.localeCompare(b.venture);
    });
  return { apps, developerUrl: data.developer?.[platform] ?? null };
}
